```css
/* Element selector */
p { color: black; }
h1 { font-size: 2rem; }

/* Class selector */
.button { background: blue; }
.card-title { font-weight: bold; }

/* ID selector (use sparingly, high specificity) */
#header { position: fixed; }
#submit-btn { border-radius: 5px; }

/* Attribute selector */
input[type="text"] { border: 1px solid gray; }
a[href^="https"] { color: green; }  /* starts with */
a[href$=".pdf"] { color: red; }    /* ends with */
[disabled] { opacity: 0.5; }

/* Descendant selector (space) */
article p { margin-bottom: 1em; }
div .highlight { background: yellow; }

/* Child selector (direct child only) */
ul > li { list-style: none; }
.container > .item { padding: 10px; }

/* Adjacent sibling selector (+) */
h2 + p { margin-top: 0; }

/* General sibling selector (~) */
h2 ~ p { color: gray; }

/* Grouping selector */
h1, h2, h3 { font-family: 'Georgia', serif; }

/* Pseudo-classes */
a:hover { text-decoration: underline; }
li:first-child { font-weight: bold; }
li:last-child { margin-bottom: 0; }
li:nth-child(odd) { background: #f9f9f9; }

/* Pseudo-elements */
p::first-line { font-weight: bold; }
h1::before { content: "★ "; color: gold; }
h1::after { content: " ★"; color: gold; }
```

