/* Hexadecimal shorthand (#RGB) */
.shorthand {
    color: #F00;  /* same as #FF0000 */
    background: #0F0; /* #00FF00 */
    border: #00F; /* #0000FF */
}

/* Hexadecimal with alpha (8-digit: #RRGGBBAA) */
.transparent-hex {
    background: #FF000080; /* 50% transparent red */
}

/* RGB - Red, Green, Blue (0-255 each) */
.rgb-example {
    color: rgb(255, 0, 0);      /* red */
    background: rgb(0, 255, 0);  /* green */
    border-color: rgb(0, 0, 255); /* blue */
}

/* RGBA - RGB with Alpha (opacity 0-1) */
.rgba-example {
    background: rgba(255, 0, 0, 0.5); /* 50% transparent red */
    color: rgba(0, 0, 0, 0.8);        /* 80% black */
}

/* HSL - Hue (0-360), Saturation (0-100%), Lightness (0-100%) */
.hsl-example {
    color: hsl(0, 100%, 50%);     /* red */
    background: hsl(120, 100%, 50%); /* green */
    border: hsl(240, 100%, 50%);  /* blue */
}

/* HSLA - with Alpha channel */
.hsla-example {
    background: hsla(240, 100%, 50%, 0.3); /* blue with 30% opacity */
    color: hsla(0, 0%, 0%, 0.7);           /* black at 70% */
}

/* currentColor keyword (inherits parent's color) */
.icon {
    color: #3498db;
    border: 1px solid currentColor; /* border matches color */
    box-shadow: 0 0 5px currentColor;
}

/* transparent keyword */
.transparent-bg {
    background: transparent;
}
