```css
/* ===== ABSOLUTE UNITS (fixed size, not recommended for responsive design) ===== */
.absolute {
    /* Pixels - most common absolute unit */
    width: 200px;
    height: 150px;
    font-size: 16px;

    /* Points (1pt = 1/72 inch) - for print */
    margin: 10pt;

    /* Centimeters/inches - for print only */
    padding: 1cm;
    border: 0.5in;
}

/* ===== RELATIVE UNITS (recommended for responsive design) ===== */

/* em - relative to parent element's font-size */
.parent-em {
    font-size: 20px;
}
.parent-em .child {
    font-size: 1.5em;  /* 20px * 1.5 = 30px */
    padding: 2em;      /* 30px * 2 = 60px (based on current element's font-size) */
}

/* rem - relative to root (html) font-size */
html {
    font-size: 16px;  /* 1rem = 16px */
}
.rem-example {
    font-size: 1.5rem;  /* 16px * 1.5 = 24px */
    margin: 2rem;       /* 32px */
    padding: 0.5rem;    /* 8px */
}

/* Percentage - relative to parent element */
.parent-percent {
    width: 500px;
}
.child-percent {
    width: 50%;    /* 250px (half of parent) */
    font-size: 80%; /* if parent is 20px, child is 16px */
}

/* Viewport units (relative to browser viewport) */
.viewport-units {
    width: 50vw;      /* 50% of viewport width */
    height: 30vh;     /* 30% of viewport height */
    font-size: 4vw;   /* scales with viewport width */
    min-height: 100vh; /* full screen height */
}

/* vmin - based on smaller dimension, vmax - based on larger dimension */
.responsive-square {
    width: 20vmin;   /* 20% of the smaller viewport dimension */
    height: 20vmin;  /* square that scales with smallest side */
}

/* ch - width of '0' character (useful for text containers) */
.text-container {
    max-width: 60ch;  /* optimal line length for readability */
}

/* ex - x-height of font */
.indent {
    text-indent: 2ex;
}

/* lh - line height unit */
.spacing {
    margin-bottom: 1.5lh;
}
```

