/* ===== DISPLAY VALUES ===== */

/* block - takes full width, starts on new line */
.block-element {
    display: block;
    width: 100%;           /* can set width/height */
    margin: 10px 0;        /* vertical margins work */
    /* Examples: <div>, <p>, <h1>, <section> */
}

/* inline - takes only content width, no new line */
.inline-element {
    display: inline;
    width: 100px;          /* IGNORED - cannot set width */
    height: 50px;          /* IGNORED - cannot set height */
    margin: 10px;          /* only horizontal margins work */
    padding: 5px;          /* padding works but may overlap */
    /* Examples: <span>, <a>, <strong>, <em> */
}

/* inline-block - hybrid: inline flow with block properties */
.inline-block-element {
    display: inline-block;
    width: 150px;          /* works! */
    height: 100px;         /* works! */
    margin: 10px;          /* works! */
    vertical-align: top;   /* alignment works */
    /* Elements sit side-by-side like inline */
}

/* none - removes element completely (no space reserved) */
.hidden-element {
    display: none;
    /* Element not rendered, space not reserved */
}

/* visibility: hidden vs display: none */
.invisible {
    visibility: hidden;    /* hides but space reserved */
}

/* flex - flexible box layout */
.flex-container {
    display: flex;
    flex-direction: row;   /* or column, row-reverse, column-reverse */
    justify-content: center; /* horizontal alignment */
    align-items: center;     /* vertical alignment */
    gap: 20px;               /* space between items */
}

/* grid - grid layout */
.grid-container {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
}

/* Other display values */
.table-display {
    display: table;
    display: table-cell;
    display: table-row;
}

.list-item {
    display: list-item;  /* like <li> with bullet */
}

/* For legacy browsers */
.legacy {
    display: -webkit-box;
    display: -moz-box;
}
```

