/* ===== FLEXBOX COMPLETE GUIDE ===== */

/* FLEX CONTAINER PROPERTIES */
.flex-container {
    display: flex;

    /* 1. flex-direction - main axis direction */
    flex-direction: row;        /* default: left to right */
    flex-direction: row-reverse; /* right to left */
    flex-direction: column;      /* top to bottom */
    flex-direction: column-reverse; /* bottom to top */

    /* 2. flex-wrap - allow items to wrap */
    flex-wrap: nowrap;      /* default: all on one line */
    flex-wrap: wrap;        /* wrap to next line */
    flex-wrap: wrap-reverse; /* wrap to reverse line */

    /* Shorthand: flex-flow (direction + wrap) */
    flex-flow: row wrap;

    /* 3. justify-content - alignment on MAIN axis */
    justify-content: flex-start;    /* default: start */
    justify-content: flex-end;      /* end */
    justify-content: center;        /* center */
    justify-content: space-between; /* space between items */
    justify-content: space-around;  /* space around items */
    justify-content: space-evenly;  /* equal space all around */

    /* 4. align-items - alignment on CROSS axis (single line) */
    align-items: stretch;     /* default: stretch to fill */
    align-items: flex-start;  /* align to top */
    align-items: flex-end;    /* align to bottom */
    align-items: center;      /* center vertically */
    align-items: baseline;    /* align by text baseline */

    /* 5. align-content - alignment of MULTIPLE lines (when wrapping) */
    align-content: stretch;     /* default */
    align-content: flex-start;
    align-content: flex-end;
    align-content: center;
    align-content: space-between;
    align-content: space-around;

    /* 6. gap - space between items */
    gap: 20px;           /* both row and column gap */
    row-gap: 10px;       /* vertical gap */
    column-gap: 20px;    /* horizontal gap */
}

/* FLEX ITEM PROPERTIES */
.flex-item {
    /* 1. order - change visual order (default 0) */
    order: 2;

    /* 2. flex-grow - how much item grows (default 0) */
    flex-grow: 1;  /* item takes available space proportionally */

    /* 3. flex-shrink - how much item shrinks (default 1) */
    flex-shrink: 1;

    /* 4. flex-basis - initial size before growing/shrinking */
    flex-basis: auto;  /* default: based on width/content */
    flex-basis: 200px; /* fixed starting size */

    /* Shorthand: flex (grow shrink basis) */
    flex: 1;           /* flex-grow: 1, flex-shrink: 1, flex-basis: 0% */
    flex: 2 1 200px;   /* grow:2, shrink:1, basis:200px */

    /* 5. align-self - override align-items for this item */
    align-self: auto;        /* default: inherit from parent */
    align-self: flex-start;
    align-self: flex-end;
    align-self: center;
    align-self: stretch;
}
