/* ===== CSS TRANSITIONS ===== */

/* Basic transition syntax */
.transition-element {
    /* Property to transition */
    transition-property: all;           /* transition all properties */
    transition-property: width, background-color; /* specific properties */

    /* Duration (required for transition to work) */
    transition-duration: 0.3s;          /* 300 milliseconds */
    transition-duration: 300ms;         /* same as above */

    /* Timing function (easing) */
    transition-timing-function: ease;    /* default: slow start, fast, slow end */
    transition-timing-function: linear;  /* constant speed */
    transition-timing-function: ease-in; /* slow start */
    transition-timing-function: ease-out; /* slow end */
    transition-timing-function: ease-in-out; /* slow both ends */
    transition-timing-function: cubic-bezier(0.25, 0.1, 0.25, 1); /* custom */

    /* Delay before starting */
    transition-delay: 0s;               /* no delay (default) */
    transition-delay: 0.2s;             /* wait 200ms before starting */

    /* Shorthand (property duration timing-function delay) */
    transition: all 0.3s ease 0s;
    transition: width 0.5s ease-in-out 0.1s;
    transition: all 0.2s linear;        /* delay omitted = 0s */

    /* Multiple transitions */
    transition: 
        width 0.3s ease,
        background-color 0.5s linear,
        transform 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

/* Hover transition example */
.button {
    background-color: #3498db;
    color: white;
    padding: 10px 20px;
    border: none;
    transition: all 0.3s ease;
}

.button:hover {
    background-color: #2980b9;
    transform: scale(1.05);
    box-shadow: 0 5px 15px rgba(0,0,0,0.3);
}

/* Transitionable properties (not all properties can be transitioned) */
.transitionable {
    /* Colors */
    transition: color 0.3s, background-color 0.3s, border-color 0.3s;

    /* Box model */
    transition: width 0.3s, height 0.3s, padding 0.3s, margin 0.3s;

    /* Positioning */
    transition: top 0.3s, left 0.3s, right 0.3s, bottom 0.3s;

    /* Transform */
    transition: transform 0.3s;

    /* Opacity */
    transition: opacity 0.3s;

    /* Shadows */
    transition: box-shadow 0.3s, text-shadow 0.3s;

    /* Filter */
    transition: filter 0.3s;
}
